/// The caller retains cleanup() and attaches its real Work to the same task
/// route before polling assemble. The constructor performs no stage creation.
pub(crate) struct PreparedLearningBuilder {
    context: Arc<OriginalSameActorRootContext>,
    learning: AgentdRootLearningInputsV1,
    factory: AgentdRootQ24ModelFactoryV1,
    publication: OriginalScopedPublicationTicket,
    retained: OriginalCellQ24RetainedLearningSourceV1,
    original: OriginalCellQ24LearningInputsV1,
    work: Arc<OriginalSameActorLearningWork>,
    closing: CloseSameActorPhaseOnDrop,
}

pub(crate) struct PreparedLearningActivation {
    context: Arc<OriginalSameActorRootContext>,
    handle: LearningIterationHandleV1,
    owners: Arc<OriginalCellQ24LearningStageOwnersV1>,
    publication: OriginalScopedPublicationTicket,
    handoff: OriginalQ24SuccessorHandoffV1,
    successor: OriginalSameActorSuccessorTaskParts,
    worker: OriginalSameActorLearningWorker,
}

impl PreparedLearningBuilder {
    pub(crate) fn new(
        scoped: OriginalSameActorScopedOwners,
        original: OriginalCellQ24LearningInputsV1,
    ) -> Result<Self, AgentdError> {
        let context = Arc::clone(scoped.context());
        let closing = CloseSameActorPhaseOnDrop::new(context.gate());
        OriginalSameActorRootContext::require_current(&context)?;
        let (same_context, learning, factory, publication, prepared, retained) =
            scoped.into_original_parts()?;
        if !Arc::ptr_eq(&context, &same_context)
            || !Arc::ptr_eq(&original.prepared, &prepared)
        {
            return Err(AgentdError::GenerationFenced(
                "learning inputs differ from the actual scoped Prepared capability".into(),
            ));
        }
        AgentdRootLearningInputsV1::require_prepared_q24(&learning, &original.prepared)?;
        if original.prepared.initial().owners.evidence_trust_digest
            != original.verifier.trust_digest()
            || !(1..=64).contains(&original.queue_capacity)
        {
            return Err(AgentdError::Invalid(
                "original Q24 trust and bounded queue required".into(),
            ));
        }
        let work =
            OriginalSameActorLearningWork::from_original_scope(Arc::clone(&context), prepared)?;
        OriginalSameActorRootContext::require_current(&context)?;
        Ok(Self {
            context,
            learning,
            factory,
            publication,
            retained,
            original,
            work,
            closing,
        })
    }

    pub(crate) fn cleanup(&self) -> OriginalSameActorLearningCleanup {
        self.work.cleanup()
    }

    pub(crate) async fn assemble(
        mut self,
        successor_capacity: usize,
    ) -> Result<PreparedLearningActivation, AgentdError> {
        OriginalSameActorRootContext::require_current(&self.context)?;
        if !(1..=64).contains(&successor_capacity) {
            return Err(AgentdError::Invalid("successor queue must be 1..64".into()));
        }
        let verifier = self.original.verifier.clone();
        let capacity = self.original.queue_capacity;
        let owners = OriginalCellQ24LearningStageOwnersV1::from_original_same_actor_inputs(
            self.original,
            self.factory,
            Arc::clone(&self.work),
        )
        .await
        .map_err(|error| AgentdError::GenerationFenced(error.to_string()))?;
        let (handle, learning) = AgentdRootLearningInputsV1::into_q24_learning_runtime(
            self.learning,
            Arc::clone(&owners),
            verifier,
            capacity,
        )?;
        // The original successor constructor requires this exact retained
        // source while the original delivery registry is still in bootstrap.
        let learning = LearningIterationRuntimeBootstrapV1::with_retained_q24_source(
            learning,
            self.retained,
            self.context.identity(),
        )?;
        let (mut learning, pending, handoff, successor) =
            prepare_original_same_actor_successor(
                learning,
                self.context.identity(),
                self.context.successor_session(),
                Arc::clone(self.context.gate()),
                successor_capacity,
            )
            .await?;
        let delivery = learning.take_circuit_delivery().ok_or_else(|| {
            AgentdError::GenerationFenced("actual retained A delivery is missing".into())
        })?;
        OriginalSameActorRootContext::require_current(&self.context)?;
        let worker = OriginalSameActorLearningWorker::from_original_parts(
            Arc::clone(&self.context),
            Arc::clone(&self.work),
            learning,
            delivery,
            pending,
        )?;
        self.closing.disarm();
        Ok(PreparedLearningActivation {
            context: self.context,
            handle,
            owners,
            publication: self.publication,
            handoff,
            successor,
            worker,
        })
    }
}

impl PreparedLearningActivation {
    pub(crate) fn into_original_parts(
        self,
    ) -> Result<
        (
            LearningIterationHandleV1,
            Arc<OriginalCellQ24LearningStageOwnersV1>,
            OriginalScopedPublicationTicket,
            OriginalQ24SuccessorHandoffV1,
            OriginalSameActorSuccessorTaskParts,
            OriginalSameActorLearningWorker,
        ),
        AgentdError,
    > {
        OriginalSameActorRootContext::require_current(&self.context)?;
        Ok((
            self.handle,
            self.owners,
            self.publication,
            self.handoff,
            self.successor,
            self.worker,
        ))
    }
}

//! Required supervision for the original Learning, retained delivery and C.
//! Every stopped or failed lane closes the same phase, then joins real work.

use std::sync::Arc;

use codex_hepta_automation::AutomationStore;
use tokio_util::sync::CancellationToken;

use crate::AgentdError;
use crate::AgentdState;
use crate::LearningIterationRuntimeBootstrapV1;
use crate::circuit_q24_successor::PendingSuccessorOwner;
use crate::learning_iteration::CircuitLearningDeliveryRuntimeV1;
use crate::root_production_inputs::same_actor_phase::OriginalSameActorRootContext;
use crate::same_actor_q24_phase_gate::CloseSameActorPhaseOnDrop;

use super::OriginalSameActorLearningWork;

pub(crate) struct OriginalSameActorLearningWorker {
    context: Arc<OriginalSameActorRootContext>,
    work: Arc<OriginalSameActorLearningWork>,
    learning: LearningIterationRuntimeBootstrapV1,
    delivery: CircuitLearningDeliveryRuntimeV1,
    pending: PendingSuccessorOwner,
    _closing: CloseSameActorPhaseOnDrop,
}

enum FirstFinished {
    Learning(Result<(), AgentdError>),
    Delivery(Result<(), AgentdError>),
    Successor(Result<(), AgentdError>),
    Closed,
}

impl OriginalSameActorLearningWorker {
    pub(super) fn from_original_parts(
        context: Arc<OriginalSameActorRootContext>,
        work: Arc<OriginalSameActorLearningWork>,
        learning: LearningIterationRuntimeBootstrapV1,
        delivery: CircuitLearningDeliveryRuntimeV1,
        pending: PendingSuccessorOwner,
    ) -> Result<Self, AgentdError> {
        let closing = CloseSameActorPhaseOnDrop::new(context.gate());
        OriginalSameActorRootContext::require_current(&context)?;
        work.require_identity_and_gate(context.identity(), context.gate())?;
        learning.require_identity(context.identity())?;
        Ok(Self {
            context,
            work,
            learning,
            delivery,
            pending,
            _closing: closing,
        })
    }

    pub(crate) async fn run(
        self,
        store: AutomationStore,
        state: Arc<AgentdState>,
        cancellation: CancellationToken,
    ) -> Result<(), AgentdError> {
        let work = Arc::clone(&self.work);
        let result = self.run_original_lanes(store, state, cancellation).await;
        work.gate().close();
        let joined = work.close_and_join_original_work().await;
        match (result, joined) {
            (Err(error), Err(join)) => Err(AgentdError::GenerationFenced(format!(
                "{error}; original learning cleanup: {join}"
            ))),
            (Err(error), Ok(())) => Err(error),
            (Ok(()), result) => result,
        }
    }

    async fn run_original_lanes(
        self,
        store: AutomationStore,
        state: Arc<AgentdState>,
        cancellation: CancellationToken,
    ) -> Result<(), AgentdError> {
        OriginalSameActorRootContext::require_current(&self.context)?;
        self.work
            .require_identity_and_gate(state.identity(), self.context.gate())?;
        CircuitLearningDeliveryRuntimeV1::attach_sources(&self.delivery, &state)?;
        let stopped = cancellation.child_token();
        let learning = self.learning.run_original_same_actor(
            Arc::clone(&state),
            stopped.clone(),
            Arc::clone(&self.work),
        );
        let delivery = self.delivery.run(store.clone(), Arc::clone(&state), stopped.clone());
        let successor = self.pending.run(store, state, stopped.clone());
        tokio::pin!(learning, delivery, successor);
        let first = tokio::select! {
            result = &mut learning => FirstFinished::Learning(result),
            result = &mut delivery => FirstFinished::Delivery(result),
            result = &mut successor => FirstFinished::Successor(result),
            _ = cancellation.cancelled() => FirstFinished::Closed,
            _ = self.context.gate().cancelled() => FirstFinished::Closed,
            _ = tokio::time::sleep_until(tokio::time::Instant::from_std(
                self.context.gate().deadline().instant(),
            )) => FirstFinished::Closed,
        };
        // Do not abort or detach any owner. In particular the Pending C worker
        // joins CURRENT/FinalUse/source work already entered by its original lane.
        self.context.gate().close();
        stopped.cancel();
        let results = match first {
            FirstFinished::Learning(result) => {
                let (delivery, successor) = tokio::join!(delivery, successor);
                [
                    ("learning", result),
                    ("delivery", delivery),
                    ("successor", successor),
                ]
            }
            FirstFinished::Delivery(result) => {
                let (learning, successor) = tokio::join!(learning, successor);
                [
                    ("learning", learning),
                    ("delivery", result),
                    ("successor", successor),
                ]
            }
            FirstFinished::Successor(result) => {
                let (learning, delivery) = tokio::join!(learning, delivery);
                [
                    ("learning", learning),
                    ("delivery", delivery),
                    ("successor", result),
                ]
            }
            FirstFinished::Closed => {
                let (learning, delivery, successor) = tokio::join!(learning, delivery, successor);
                [
                    ("learning", learning),
                    ("delivery", delivery),
                    ("successor", successor),
                ]
            }
        };
        let failures: Vec<String> = results
            .into_iter()
            .filter_map(|(lane, result)| result.err().map(|error| format!("{lane}: {error}")))
            .collect();
        if failures.is_empty() {
            return Err(AgentdError::GenerationFenced(
                "original required learning lanes stopped".into(),
            ));
        }
        Err(AgentdError::GenerationFenced(failures.join("; ")))
    }
}

